            if (Fs.statSync(currentFileFullPath).isDirectory()) {
                load(currentFileFullPath, '/', files);
            }
            else {
                load(root, currentFile, files);
            }
        }

        return register(files);
    };

    var register = function (files) {

        for (var i = 0, il = files.length; i < il; ++i) {
            var file = files[i];
